import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
public class DemoListas {
    static Producto buscar(List<Producto> lista, String codigo) {
        for (Producto p : lista) {
            if (p.getCodigo().equals(codigo)) return p;
        }
        return null;
    }
    public static void main(String[] args) {
        List<Producto> productos = new ArrayList<>();
        productos.add(new Producto("A1", "Teclado", 5));
        productos.add(new Producto("B2", "Raton", 0));
        Producto encontrado = buscar(productos, "A1");

        if (encontrado != null) {
            System.out.println(encontrado.getNombre());
        }
        Iterator<Producto> it = productos.iterator();
        while (it.hasNext()) {
            if (it.next().getStock() == 0) it.remove();
        }
        System.out.println(productos.size());
    }
}

