import java.util.Objects;
final class Contacto {
    private final String nombre;
    private final String telefono;
    Contacto(String nombre, String telefono) {
        this.nombre = Objects.requireNonNull(nombre);
        this.telefono = Objects.requireNonNull(telefono);
    }
    String getNombre() { return nombre; }

@Override
public boolean equals(Object otro) {
    if (this == otro) return true;
    if (!(otro instanceof Contacto contacto)) return false;
    return telefono.equals(contacto.telefono);
}

import java.util.ArrayList;
import java.util.List;
public class DemoIgualdad {
    public static void main(String[] args) {
        Contacto a = new Contacto("Ana", "600111111");
        Contacto b = new Contacto("Otra Ana", "600111111");
        List<Contacto> lista = new ArrayList<>();
        lista.add(a);
        System.out.println(a == b);
        System.out.println(a.equals(b));
        System.out.println(a.hashCode() == b.hashCode());
        System.out.println(lista.contains(b));
    }
}

